190	  const updatePoint = (event: PointerEvent<HTMLDivElement>) => {
191	    const bounds = event.currentTarget.getBoundingClientRect();
192	    return {
193	      x: Math.min(1, Math.max(0, (event.clientX - bounds.left) / bounds.width)),
