8	import { useMemberStore } from "@/hooks/useMemberStore";
9	import { getMemberFullName } from "@/utils/memberUtils";
10	
11	// Names beyond this count collapse into a "+K more" suffix.
12	const MAX_VISIBLE_NAMES = 2;
13	
14	type Props = {
15	  image: GalleryImage;
16	  onClick: () => void;
17	};
18	
19	export const ImageCard = ({ image, onClick }: Props) => {
20	  const { t } = useTranslation(undefined, {
21	    keyPrefix: "gallery-view.view",
22	  });
23	  const members = useMemberStore((state) => state.members);
24	
25	  const linkedNames = useMemo(
26	    () =>
27	      image.linkedMemberIds
28	        .map((id) => members.find((member) => member.id === id))
29	        .filter((member) => !!member)
30	        .map(getMemberFullName),
31	    [image.linkedMemberIds, members],
32	  );
33	
34	  const visibleNames = linkedNames.slice(0, MAX_VISIBLE_NAMES);
35	  const extraCount = linkedNames.length - visibleNames.length;
36	
37	  const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
38	    if (e.key === "Enter" || e.key === " ") {
39	      e.preventDefault();
40	      onClick();
41	    }
42	  };
43	
44	  return (
45	    <Card
46	      role="button"
47	      tabIndex={0}
48	      aria-label={image.title || t("image-alt-fallback")}
49	      onClick={onClick}
50	      onKeyDown={handleKeyDown}
51	      className="cursor-pointer overflow-hidden relative group flex flex-col h-full"
52	    >
53	      <CardHeader className="p-0 bg-muted/20 flex-1 min-h-0">
54	        <div className="overflow-hidden h-full w-full">
55	          <AuthenticatedImage
56	            src={image.imageData}
57	            alt=""
58	            className="w-full h-full object-cover pointer-events-none group-hover:scale-105 transition-transform duration-300"
59	          />
60	        </div>
61	      </CardHeader>
62	      <CardContent className="p-2 pb-1 shrink-0">
63	        <h3 className="font-semibold truncate text-xs leading-tight">
64	          {image.title}
65	        </h3>
66	        <p className="text-[10px] text-muted-foreground mt-0.5">
67	          {formatDate(image.createdAt)}
68	        </p>
69	        <p
70	          className={`flex items-center gap-1 text-[10px] text-muted-foreground mt-0.5 truncate ${
71	            linkedNames.length === 0 ? "invisible" : ""
72	          }`}
73	          title={linkedNames.length > 0 ? linkedNames.join(", ") : undefined}
74	        >
75	          <Users className="size-2.5 shrink-0" />
76	          <span className="truncate">
77	            {visibleNames.join(", ")}
78	            {extraCount > 0 &&
79	              ` ${t("linked-members-more", { count: extraCount })}`}
80	          </span>
81	        </p>
82	      </CardContent>
83	    </Card>
84	  );
85	};
