1	import {
2	  CalendarIcon,
3	  ChevronLeftIcon,
4	  ChevronRightIcon,
5	  XIcon,
6	} from "lucide-react";
7	import { Button } from "@/components/ui/button";
8	import { Calendar } from "@/components/ui/calendar";
9	import { Input } from "@/components/ui/input";
10	import {
11	  Popover,
12	  PopoverAnchor,
13	  PopoverContent,
14	  PopoverTrigger,
15	} from "@/components/ui/popover";
16	import { useState, useEffect } from "react";
17	import { cn } from "@/lib/utils";
18	import {
19	  DatePrecision,
20	  formatPartialDateForInput,
21	  getDatePrecision,
22	  parsePartialDateInput,
23	  resolveDateLocale,
24	} from "@/utils/dateUtils";
25	import { useTranslation } from "react-i18next";
26	
27	type Props = {
28	  className?: string;
29	  value?: string | null;
30	  onChange?: (value: string | null) => void;
31	  placeholder?: string;
32	};
33	
34	const YEAR_MIN = 1400;
35	const YEAR_MAX = new Date().getFullYear();
36	
37	function getMonthNames(locale: string): string[] {
38	  return Array.from({ length: 12 }, (_, i) =>
39	    new Intl.DateTimeFormat(locale, { month: "short" }).format(
40	      new Date(2000, i, 1),
41	    ),
42	  );
43	}
44	
45	function parseParts(value: string | null | undefined): {
46	  year: number | null;
47	  month: number | null;
48	  day: number | null;
49	} {
50	  if (!value) return { year: null, month: null, day: null };
51	  const parts = value.split("-").map(Number);
52	  return {
53	    year: parts[0] ?? null,
54	    month: parts[1] ?? null,
55	    day: parts[2] ?? null,
56	  };
57	}
58	
59	export const PartialDatePicker = ({
60	  className,
61	  value,
62	  onChange,
63	  placeholder,
64	}: Props) => {
65	  const { t, i18n } = useTranslation();
66	  const language = i18n.resolvedLanguage;
67	  const locale = resolveDateLocale(language);
68	  const monthNames = getMonthNames(locale);
69	  const today = new Date();
70	
71	  // Editable text representation of the value, kept in sync while not focused.
72	  const inputText = formatPartialDateForInput(value, language);
73	  const [text, setText] = useState(inputText);
74	  const [focused, setFocused] = useState(false);
75	  useEffect(() => {
76	    if (!focused) setText(inputText);
77	  }, [inputText, focused]);
78	
79	  const textIsInvalid =
80	    focused &&
81	    text.trim() !== "" &&
82	    !parsePartialDateInput(text, language).valid;
83	
84	  const handleTextChange = (next: string) => {
85	    setText(next);
86	    if (next.trim() === "") {
87	      onChange?.(null);
88	      return;
89	    }
90	    const parsed = parsePartialDateInput(next, language);
91	    if (parsed.valid && parsed.value) onChange?.(parsed.value);
92	  };
93	
94	  const handleTextBlur = () => {
95	    setFocused(false);
96	    if (text.trim() === "") {
97	      setText("");
98	      return;
99	    }
100	    const parsed = parsePartialDateInput(text, language);
101	    setText(
102	      parsed.valid && parsed.value
103	        ? formatPartialDateForInput(parsed.value, language)
104	        : inputText,
105	    );
106	  };
107	
108	  const inferredPrecision: DatePrecision =
109	    getDatePrecision(value ?? null) ?? "day";
110	  const [open, setOpen] = useState(false);
111	  const [activePrecision, setActivePrecision] =
112	    useState<DatePrecision>(inferredPrecision);
113	
114	  // viewYear drives decade navigation in Year mode and month grid in Month mode.
115	  const { year: parsedYear, month: parsedMonth } = parseParts(value);
116	  const [viewYear, setViewYear] = useState(parsedYear ?? YEAR_MAX);
117	
118	  // Sync view when value changes externally (e.g. form reset).
119	  useEffect(() => {
120	    if (parsedYear) setViewYear(parsedYear);
121	  }, [parsedYear]);
122	
123	  // When popover opens, sync activePrecision to the current value's precision.
124	  const handleOpenChange = (next: boolean) => {
125	    if (next) {
126	      setActivePrecision(getDatePrecision(value ?? null) ?? "day");
127	      if (!value) setViewYear(today.getFullYear());
128	    }
129	    setOpen(next);
130	  };
131	
132	  const switchPrecision = (p: DatePrecision) => {
133	    setActivePrecision(p);
134	    // Trim value to the new precision on the fly so the display updates.
135	    if (!value) return;
136	    if (p === "year" && parsedYear) {
137	      onChange?.(`${parsedYear}`);
138	    } else if (p === "month" && parsedYear) {
139	      const m = parsedMonth ?? 1;
140	      onChange?.(`${parsedYear}-${String(m).padStart(2, "0")}`);
141	    }
142	    // "day" — keep full date as-is (or let user pick via calendar)
143	  };
144	
145	  const handleYearSelect = (y: number) => {
146	    onChange?.(`${y}`);
147	    setOpen(false);
148	  };
149	
150	  const handleMonthSelect = (m: number) => {
151	    onChange?.(`${viewYear}-${String(m).padStart(2, "0")}`);
152	    setOpen(false);
153	  };
154	
155	  const handleDaySelect = (date: Date | undefined) => {
156	    if (!date) {
157	      onChange?.(null);
158	    } else {
159	      const y = date.getFullYear();
160	      const m = String(date.getMonth() + 1).padStart(2, "0");
161	      const d = String(date.getDate()).padStart(2, "0");
162	      onChange?.(`${y}-${m}-${d}`);
163	    }
164	    setOpen(false);
165	  };
166	
167	  const clearValue = () => {
168	    onChange?.(null);
169	    setOpen(false);
170	  };
171	
172	  // ── Decade grid for Year mode ───────────────────────────────────────────────
173	  const decadeStart = Math.floor(viewYear / 10) * 10;
174	  const decadeYears = Array.from({ length: 12 }, (_, i) => decadeStart - 1 + i);
175	
176	  // ── Derived Calendar value ──────────────────────────────────────────────────
177	  const calendarValue =
178	    parsedYear && parsedMonth && parseParts(value).day
179	      ? new Date(parsedYear, parsedMonth - 1, parseParts(value).day!)
180	      : undefined;
181	
182	  const PRECISION_LABELS: Record<NonNullable<DatePrecision>, string> = {
183	    year: "Y",
184	    month: "M",
185	    day: "D",
186	  };
187	
188	  return (
189	    <Popover open={open} onOpenChange={handleOpenChange}>
190	      <PopoverAnchor asChild>
191	        <div className="relative">
192	          <Input
193	            value={text}
194	            onChange={(e) => handleTextChange(e.target.value)}
195	            onFocus={() => setFocused(true)}
196	            onBlur={handleTextBlur}
197	            placeholder={t("common.date-input-hint")}
198	            aria-label={placeholder ?? t("common.date-input-hint")}
199	            aria-invalid={textIsInvalid}
200	            className={cn("pr-12", className)}
201	          />
202	          <div className="absolute inset-y-0 right-1 flex items-center gap-0.5">
203	            {value && (
204	              <button
205	                type="button"
206	                aria-label={t("common.clear-date")}
207	                className="flex size-5 items-center justify-center rounded-sm text-muted-foreground opacity-60 hover:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
208	                onClick={clearValue}
209	              >
210	                <XIcon className="h-3 w-3" aria-hidden="true" />
211	              </button>
212	            )}
213	            <PopoverTrigger asChild>
214	              <button
215	                type="button"
216	                aria-label={t("common.open-date-picker")}
217	                className="flex size-5 items-center justify-center rounded-sm text-muted-foreground opacity-70 hover:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
218	              >
219	                <CalendarIcon className="h-4 w-4" aria-hidden="true" />
220	              </button>
221	            </PopoverTrigger>
222	          </div>
223	        </div>
224	      </PopoverAnchor>
225	      <PopoverContent className="w-auto p-0" align="start">
226	        {/* Precision tabs */}
227	        <div className="flex border-b">
228	          {(["year", "month", "day"] as NonNullable<DatePrecision>[]).map(
229	            (p) => (
230	              <button
231	                key={p}
232	                type="button"
233	                onClick={() => switchPrecision(p)}
234	                className={cn(
235	                  "flex-1 py-1.5 text-xs font-medium transition-colors",
236	                  activePrecision === p
237	                    ? "border-b-2 border-primary text-primary"
238	                    : "text-muted-foreground hover:text-foreground",
239	                )}
240	              >
241	                {PRECISION_LABELS[p]}
242	              </button>
243	            ),
244	          )}
245	        </div>
246	
247	        {/* Year picker */}
248	        {activePrecision === "year" && (
249	          <div className="p-2 w-[224px]">
250	            <div className="flex items-center justify-between mb-2">
251	              <Button
252	                variant="ghost"
253	                size="icon"
254	                className="h-6 w-6"
255	                type="button"
256	                onClick={() => setViewYear((y) => Math.max(y - 10, YEAR_MIN))}
257	                disabled={decadeStart <= YEAR_MIN}
258	              >
259	                <ChevronLeftIcon className="h-3 w-3" />
260	              </Button>
261	              <span className="text-xs font-medium">
262	                {decadeStart} – {Math.min(decadeStart + 9, YEAR_MAX)}
263	              </span>
264	              <Button
265	                variant="ghost"
266	                size="icon"
267	                className="h-6 w-6"
268	                type="button"
269	                onClick={() => setViewYear((y) => Math.min(y + 10, YEAR_MAX))}
270	                disabled={decadeStart + 10 > YEAR_MAX}
271	              >
272	                <ChevronRightIcon className="h-3 w-3" />
273	              </Button>
274	            </div>
275	            <div className="grid grid-cols-3 gap-1">
276	              {decadeYears.map((y) => {
277	                const outOfRange = y < YEAR_MIN || y > YEAR_MAX;
278	                return (
279	                  <button
280	                    key={y}
281	                    type="button"
282	                    disabled={outOfRange}
283	                    onClick={() => !outOfRange && handleYearSelect(y)}
284	                    className={cn(
285	                      "rounded px-1 py-1.5 text-xs transition-colors",
286	                      outOfRange && "opacity-25 cursor-default",
287	                      parsedYear === y
288	                        ? "bg-primary text-primary-foreground font-semibold"
289	                        : !outOfRange && "hover:bg-accent",
290	                    )}
291	                  >
292	                    {y}
293	                  </button>
294	                );
295	              })}
296	            </div>
297	          </div>
298	        )}
299	
300	        {/* Month picker */}
301	        {activePrecision === "month" && (
302	          <div className="p-2 w-[224px]">
303	            <div className="flex items-center justify-between mb-2">
304	              <Button
305	                variant="ghost"
306	                size="icon"
307	                className="h-6 w-6"
308	                type="button"
309	                onClick={() => setViewYear((y) => Math.max(y - 1, YEAR_MIN))}
310	                disabled={viewYear <= YEAR_MIN}
311	              >
312	                <ChevronLeftIcon className="h-3 w-3" />
313	              </Button>
314	              <span className="text-xs font-medium">{viewYear}</span>
315	              <Button
316	                variant="ghost"
317	                size="icon"
318	                className="h-6 w-6"
319	                type="button"
320	                onClick={() => setViewYear((y) => Math.min(y + 1, YEAR_MAX))}
321	                disabled={viewYear >= YEAR_MAX}
322	              >
323	                <ChevronRightIcon className="h-3 w-3" />
324	              </Button>
325	            </div>
326	            <div className="grid grid-cols-3 gap-1">
327	              {monthNames.map((name, idx) => {
328	                const m = idx + 1;
329	                const isSelected = parsedYear === viewYear && parsedMonth === m;
330	                return (
331	                  <button
332	                    key={m}
333	                    type="button"
334	                    onClick={() => handleMonthSelect(m)}
335	                    className={cn(
336	                      "rounded px-1 py-1.5 text-xs transition-colors",
337	                      isSelected
338	                        ? "bg-primary text-primary-foreground font-semibold"
339	                        : "hover:bg-accent",
340	                    )}
341	                  >
342	                    {name}
343	                  </button>
344	                );
345	              })}
346	            </div>
347	          </div>
348	        )}
349	
350	        {/* Day picker — full calendar */}
351	        {activePrecision === "day" && (
352	          <Calendar
353	            mode="single"
354	            selected={calendarValue}
355	            captionLayout="dropdown"
356	            onSelect={handleDaySelect}
357	            startMonth={new Date(YEAR_MIN, 0)}
358	            endMonth={new Date(YEAR_MAX, 11)}
359	            defaultMonth={
360	              calendarValue ??
361	              (parsedYear ? new Date(viewYear, (parsedMonth ?? 1) - 1) : today)
362	            }
363	          />
364	        )}
365	      </PopoverContent>
366	    </Popover>
367	  );
368	};
