14	/** Runtime guard for data received from the gallery API. */
15	function isGalleryImageDB(image: unknown): image is GalleryImageDB {
16	  return (
17	    typeof image === "object" &&
18	    image !== null &&
19	    typeof (image as GalleryImageDB).id === "string" &&
20	    typeof (image as GalleryImageDB).imageData === "string" &&
21	    ((image as GalleryImageDB).title === null ||
22	      typeof (image as GalleryImageDB).title === "string") &&
23	    ((image as GalleryImageDB).description === null ||
24	      typeof (image as GalleryImageDB).description === "string") &&
25	    typeof (image as GalleryImageDB).createdAt === "string" &&
26	    typeof (image as GalleryImageDB).uploadedAt === "string"
27	  );
28	}
