30	export interface AddGalleryImageOptions {
31	  /** When false, skip the post-add refreshGalleryImages / refreshStorageUsage /
32	   * invalidateActivityView. Useful for bulk uploads that batch the refresh at
33	   * the end. Default (undefined / true) keeps current single-upload behaviour. */
34	  refresh?: boolean;
35	}
36	
37	/** The raw picked file plus metadata for a new gallery image. The file is
38	 *  streamed as multipart form-data — no base64 is retained in store state. */
39	export interface NewGalleryImage {
40	  file: File;
41	  title: string | null;
42	  description: string | null;
43	  linkedMemberIds: string[];
44	}
45	
46	interface GalleryState {
47	  galleryImages: GalleryImage[];
48	  initialized: boolean;
49	  refreshGalleryImages: (treeId?: string) => Promise<void>;
50	  addGalleryImage: (
51	    image: NewGalleryImage,
52	    opts?: AddGalleryImageOptions,
53	  ) => Promise<string | undefined>;
54	  updateGalleryImage: (
55	    id: string,
56	    changes: Partial<GalleryImage>,
57	  ) => Promise<void>;
58	  deleteGalleryImage: (id: string) => Promise<void>;
59	  /** Tag a face region as an unknown person; persists immediately (unlike
60	   *  member links, which batch on Save) so its research task is created
61	   *  exactly once. */
62	  addUnknownFace: (
63	    imageId: string,
64	    region: { x: number; y: number; w: number; h: number },
65	    task: { title: string | null; notes: string | null },
66	  ) => Promise<void>;
67	  updateUnknownFace: (
68	    faceId: string,
69	    region: { x: number; y: number; w: number; h: number },
70	  ) => Promise<void>;
