76	export const useGalleryStore = create<GalleryState>((set, get) => ({
77	  galleryImages: [],
78	  initialized: false,
79	
80	  refreshGalleryImages: async (treeId = activeTreeId()) => {
81	    if (!treeId) {
82	      set({ galleryImages: [] });
83	      return;
84	    }
85	
86	    const [imagesResult, linksResult, unknownFacesResult] = await Promise.all([
87	      TreeService.getGalleryImages(treeId),
88	      TreeService.getGalleryMemberLinks(treeId),
89	      TreeService.getGalleryUnknownFaces(treeId),
90	    ]);
91	
92	    if (!isActiveTree(treeId)) return; // tree switched/disconnected mid-flight — drop stale data
93	
94	    const linksByImage = new Map<string, GalleryMemberLink[]>();
95	    for (const link of linksResult) {
96	      linksByImage.set(
97	        link.gallery_image_id,
98	        (linksByImage.get(link.gallery_image_id) ?? []).concat({
99	          memberId: link.member_id,
100	          x: link.x,
101	          y: link.y,
102	          w: link.w,
103	          h: link.h,
104	        }),
105	      );
106	    }
107	
108	    const facesByImage = new Map<string, UnknownFace[]>();
109	    for (const face of unknownFacesResult) {
110	      facesByImage.set(
111	        face.gallery_image_id,
112	        (facesByImage.get(face.gallery_image_id) ?? []).concat({
113	          id: face.id,
114	          galleryImageId: face.gallery_image_id,
115	          x: face.x,
116	          y: face.y,
117	          w: face.w,
118	          h: face.h,
119	          taskId: face.task_id,
120	          createdAt: face.created_at,
121	        }),
122	      );
123	    }
124	
125	    const images = imagesResult.filter(isGalleryImageDB).map((row) => {
126	      const memberLinks = linksByImage.get(row.id) ?? [];
127	      return {
128	        ...row,
129	        linkedMemberIds: memberLinks.map((link) => link.memberId),
130	        memberLinks,
131	        unknownFaces: facesByImage.get(row.id) ?? [],
132	      };
133	    });
134	
135	    set({ galleryImages: images, initialized: true });
136	  },
137	
138	  addGalleryImage: async (
139	    image: NewGalleryImage,
140	    opts?: AddGalleryImageOptions,
141	  ) => {
142	    const treeId = activeTreeId();
143	    if (!treeId) return undefined;
144	
145	    const id = crypto.randomUUID();
146	    const now = new Date().toISOString();
147	    // The file streams as multipart; member links are created in the same
148	    // request (image.linkedMemberIds).
149	    await TreeService.uploadGalleryImage(
150	      treeId,
151	      id,
152	      image.file,
153	      {
154	        title: image.title,
155	        description: image.description,
156	        memberIds: image.linkedMemberIds ?? [],
157	      },
158	      now,
159	    );
160	
161	    if (opts?.refresh !== false) {
162	      await get().refreshGalleryImages(treeId);
163	      useStorageStore.getState().refreshStorageUsage();
164	      invalidateActivityView();
165	    }
166	
167	    return id;
168	  },
169	
170	  updateGalleryImage: async (id: string, changes: Partial<GalleryImage>) => {
171	    const treeId = activeTreeId();
172	    if (!treeId) return;
173	
174	    const { linkedMemberIds, memberLinks } = changes;
175	
176	    await TreeService.updateGalleryImage(treeId, id, changes);
177	
178	    if (memberLinks) {
179	      await TreeService.setGalleryImageLinks(treeId, id, memberLinks);
180	    } else if (linkedMemberIds) {
181	      await TreeService.setGalleryImageLinks(
182	        treeId,
183	        id,
184	        linkedMemberIds.map((memberId) => ({
185	          memberId,
186	          x: null,
187	          y: null,
188	          w: null,
189	          h: null,
190	        })),
191	      );
192	    }
193	
194	    await get().refreshGalleryImages(treeId);
195	    // Editing only touches metadata/links — image bytes (and therefore storage
196	    // usage) can't change here, so no storage refresh is needed.
197	    invalidateActivityView();
198	  },
199	
200	  deleteGalleryImage: async (id: string) => {
201	    const treeId = activeTreeId();
202	    if (!treeId) return;
203	    await TreeService.removeGalleryImage(treeId, id);
204	    await get().refreshGalleryImages(treeId);
205	    useStorageStore.getState().refreshStorageUsage();
206	    invalidateActivityView();
207	  },
208	
209	  addUnknownFace: async (
210	    imageId: string,
211	    region: { x: number; y: number; w: number; h: number },
212	    task: { title: string | null; notes: string | null },
213	  ) => {
214	    const treeId = activeTreeId();
215	    if (!treeId) return;
216	
217	    await TreeService.addGalleryUnknownFace(treeId, imageId, {
