148	 * and `{ value: null, valid: false }` for anything unparseable.
149	 */
150	export function parsePartialDateInput(
151	  text: string,
152	  language?: string,
153	): { value: string | null; valid: boolean } {
154	  const trimmed = text.trim();
155	  if (!trimmed) return { value: null, valid: true };
156	
157	  const invalid = { value: null, valid: false } as const;
158	
159	  const tokens = trimmed.split(/[\s./-]+/).filter(Boolean);
160	  if (tokens.length === 0 || tokens.length > 3) return invalid;
161	  if (!tokens.every((token) => /^\d+$/.test(token))) return invalid;
