177	    const yearIndex = tokens.findIndex((token) => token.length === 4);
178	    if (yearIndex === -1) return invalid;
179	    year = Number(tokens[yearIndex]);
180	    const rest = tokens.filter((_, i) => i !== yearIndex);
181	    if (rest.length === 1) {
