221	export function formatDate(
222	  dateString: DateInput,
223	  options: FormatDateOptions = {},
224	): string {
225	  if (!dateString) return "";
226	  if (typeof dateString === "string") {
227	    const precision = getDatePrecision(dateString);
228	    const { language, ...intlOptions } = options;
229	    const locale = resolveDateLocale(language);
230	    if (precision === "year") {
231	      return dateString.slice(0, 4);
232	    }
233	    if (precision === "month") {
234	      const [year, month] = dateString.split("-").map(Number);
235	      const d = new Date(year, month - 1, 1);
236	      return new Intl.DateTimeFormat(locale, {
237	        year: "numeric",
238	        month: "long",
239	        ...intlOptions,
240	      }).format(d);
241	    }
242	    if (precision === "day") {
243	      const [y, mo, day] = dateString.split("-").map(Number);
244	      const d = new Date(y, mo - 1, day);
245	      return new Intl.DateTimeFormat(locale, {
246	        day: "2-digit",
247	        month: "2-digit",
248	        year: "numeric",
249	        ...intlOptions,
250	      }).format(d);
251	    }
252	    // Unrecognized string — fall through to Date parse for full ISO timestamps (event dates, etc.)
253	  }
254	  const date = parseDateInput(dateString);
255	  if (!date) return "";
256	  const { language, ...intlOptions } = options;
257	  return new Intl.DateTimeFormat(resolveDateLocale(language), {
258	    day: "2-digit",
259	    month: "2-digit",
260	    year: "numeric",
261	    ...intlOptions,
262	  }).format(date);
263	}
264	
265	export function formatDateTime(
266	  dateString: DateInput,
267	  options: FormatDateOptions = {},
268	): string {
269	  return formatDate(dateString, {
270	    hour: "2-digit",
271	    minute: "2-digit",
272	    second: "2-digit",
273	    ...options,
274	  });
275	}
276	
277	export function resolveDateLocale(language = i18n.resolvedLanguage): string {
278	  const fallbackLanguage = i18n.language?.split("-")[0];
279	  const baseLanguage = language?.split("-")[0] ?? fallbackLanguage;
280	  return LANGUAGE_LOCALES[baseLanguage] ?? LANGUAGE_LOCALES.en;
281	}
282	
283	function parseDateInput(dateInput: Date | string): Date | null {
284	  if (dateInput instanceof Date) {
285	    return Number.isNaN(dateInput.getTime()) ? null : dateInput;
286	  }
287	
288	  const dateOnlyParts = DATE_ONLY_RE.exec(dateInput);
289	  const date = dateOnlyParts
290	    ? new Date(
291	        Number(dateOnlyParts[1]),
292	        Number(dateOnlyParts[2]) - 1,
293	        Number(dateOnlyParts[3]),
294	      )
295	    : new Date(dateInput);
296	
297	  return Number.isNaN(date.getTime()) ? null : date;
298	}
